namespace duckdb_vergesort
{
namespace detail
{
    // Returns floor(log2(n)), assumes n > 0
    template<typename Integer>
    Integer log2(Integer n)
    {
        Integer log = 0;
        while (n >>= 1) {
            ++log;
        }
        return log;
    }
}}

