#include <algorithm>

namespace duckdb_vergesort
{
namespace detail
{
    template<typename Iterator, typename Compare>
    void iter_sort3(Iterator a, Iterator b, Iterator c,
                    Compare compare)
    {
        if (compare(*b, *a)) { std::iter_swap(a, b); }
        if (compare(*c, *b)) { std::iter_swap(b, c); }
        if (compare(*b, *a)) { std::iter_swap(a, b); }
    }
}}

